import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    text = "" if example_str is None else str(example_str)

    outside_parts = []
    depth = 0

    for char in text:
        if char == "[":
            depth += 1
        elif char == "]":
            if depth > 0:
                depth -= 1
            else:
                outside_parts.append(char)
        elif depth == 0:
            outside_parts.append(char)

    extracted_text = re.sub(r"\s+", " ", "".join(outside_parts)).strip()
    if not extracted_text or not re.search(r"\w", extracted_text):
        return {}

    vectorizer = TfidfVectorizer(token_pattern=r"(?u)\b\w+\b")
    matrix = vectorizer.fit_transform([extracted_text])

    words = vectorizer.get_feature_names_out()
    scores = np.asarray(matrix.toarray()).ravel()

    return {word: float(score) for word, score in zip(words, scores)}
